PRAGMA foreign_keys = ON;
CREATE TABLE admins (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, admin_id INTEGER NOT NULL REFERENCES admins(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE variants (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, label TEXT NOT NULL, weight_kg INTEGER NOT NULL, price_paisa INTEGER NOT NULL DEFAULT 0, stock_qty INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, UNIQUE(product_id,weight_kg));
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_code TEXT NOT NULL UNIQUE, customer_name TEXT NOT NULL, phone TEXT NOT NULL, district TEXT NOT NULL, upazila TEXT NOT NULL DEFAULT '', address TEXT NOT NULL, payment_method TEXT NOT NULL CHECK(payment_method IN ('cod','advance')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','processing','shipped','delivered','cancelled')), subtotal_paisa INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, variant_id INTEGER NOT NULL REFERENCES variants(id), product_name TEXT NOT NULL, variant_label TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price_paisa INTEGER NOT NULL, line_total_paisa INTEGER NOT NULL);
CREATE INDEX idx_orders_created ON orders(created_at DESC);
INSERT INTO products(slug,name,description,sort_order) VALUES ('jhola','ঝোলা খেজুরের গুড়','প্রাকৃতিক স্বাদের ঐতিহ্যবাহী খেজুরের গুড়।',1),('patali','পাটালি খেজুরের গুড়','ঐতিহ্যবাহী পদ্ধতিতে তৈরি পাটালি খেজুরের গুড়।',2);
INSERT INTO variants(product_id,label,weight_kg) SELECT id,'১ কেজি',1 FROM products;
INSERT INTO variants(product_id,label,weight_kg) SELECT id,'২ কেজি',2 FROM products;
